import{_ as l,o as i,c as e,a2 as a}from"./chunks/framework.CDU0sSpB.js";const _=JSON.parse('{"title":"默认清单","description":"Hearth 的审批前检查、完成前检查和任务覆盖边界。","frontmatter":{"title":"默认清单","description":"Hearth 的审批前检查、完成前检查和任务覆盖边界。","outline":[2]},"headers":[],"relativePath":"reference/checklists.md","filePath":"reference/checklists.md","lastUpdated":1794305977000}'),r={name:"reference/checklists.md"};function d(o,t,s,n,c,h){return i(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="默认清单" tabindex="-1">默认清单 <a class="header-anchor" href="#默认清单" aria-label="Permalink to &quot;默认清单&quot;">​</a></h1><p class="lead">清单应当放进任务模板、审批界面和验收流程，而不是只留在文档里。它帮助用户确认系统没有把“看起来完成”当成“真正完成”。</p><h2 id="审批与完成前检查" tabindex="-1">审批与完成前检查 <a class="header-anchor" href="#审批与完成前检查" aria-label="Permalink to &quot;审批与完成前检查&quot;">​</a></h2><p>外部动作发生前，逐项确认：</p><ul><li>[ ] 动作类型和真实意图一致；</li><li>[ ] 目标验收条件、约束和禁止动作已经检查；</li><li>[ ] 目标收件人、文件、账户、设备或资源正确；</li><li>[ ] 内容和附件正确；</li><li>[ ] 没有超出当前授权范围；</li><li>[ ] 是否可逆、可能影响什么已经说明；</li><li>[ ] 审批仍在有效期内，且没有被重复使用；</li><li>[ ] 审批绑定解析后的真实动作和参数指纹，参数变化会使审批失效；</li><li>[ ] 失败、重试和对账方式已经准备；</li><li>[ ] 没有绕过网络、凭据或安全边界。</li></ul><p>读取和整理可以在任务范围内授权；发送、发布、删除、付款和设备操作需要明确确认；不可逆动作即使已经预授权，也要有对象、金额或时间上的硬限制。</p><p>任务标记完成前，逐项确认：</p><ul><li>[ ] 目标产物存在，用户能够找到；</li><li>[ ] 目标契约的每项验收条件都有结论和证据引用；</li><li>[ ] 验证器已经通过，而不是只听执行器说完成；</li><li>[ ] 关键事实有来源，修改有差异或版本；</li><li>[ ] 没有未授权的副作用；</li><li>[ ] 外部动作有回执，不确定结果已经对账；</li><li>[ ] 不确定效果已进入显式对账队列并有用户结论；</li><li>[ ] 失败、跳过和未完成事项已经说明；</li><li>[ ] Token、时间、人工分钟和成本已经记录；</li><li>[ ] 工作区、临时权限和执行权已经回收；</li><li>[ ] 交接带 generation 和证据，旧代次结果没有推进新状态；</li><li>[ ] 沙箱路径、网络、进程和凭据边界未被绕过，越界尝试已失败关闭；</li><li>[ ] 用户可以查看、撤销、重试或继续。</li></ul><h2 id="覆盖边界" tabindex="-1">覆盖边界 <a class="header-anchor" href="#覆盖边界" aria-label="Permalink to &quot;覆盖边界&quot;">​</a></h2><p>Hearth 不承诺“任何软件、任何场景、100% 无人值守”。它承诺的是：对选择的个人数字工作提供端到端覆盖，对无法可靠完成的工作安全停下并交给人，对每次完成给出证据、权限记录和回执。</p><table tabindex="0"><thead><tr><th>成熟度</th><th>含义</th></tr></thead><tbody><tr><td>可尝试</td><td>系统能进入任务族并生成草稿</td></tr><tr><td>可完成</td><td>在代表性任务上通过验证</td></tr><tr><td>可依赖</td><td>多次真实使用稳定，失败可恢复</td></tr><tr><td>可主动</td><td>在授权范围内无需人工触发</td></tr><tr><td>可无人值守</td><td>长时间运行且风险可控</td></tr></tbody></table><p>“可尝试”不能当作“可依赖”，“可完成”也不能当作“可无人值守”。阶段验收按真实任务和证据判断，不按功能名称判断。</p>',12)])])}const u=l(r,[["render",d]]);export{_ as __pageData,u as default};
